                List.of(item("X", "298.50", 1, "0.10")),
                "RETIRADA_LOJA", null, "BOLETO", 1, "BRONZE", "SUDESTE"));
        assertThat(par298.seguro()).isEqualByComparingTo("2.98");
    }

