1	package com.loja.checkout.dominio;
2	
3	import com.loja.checkout.dominio.clube.NivelClube;
4	import com.loja.checkout.dominio.cupom.ContextoCupom;
5	import com.loja.checkout.dominio.cupom.Cupom;
6	import com.loja.checkout.dominio.entrega.ModalidadeEntrega;
7	import com.loja.checkout.dominio.pagamento.FormaPagamento;
8	import com.loja.checkout.dominio.pagamento.ResultadoPagamento;
9	import com.loja.checkout.web.ItemRequest;
10	import com.loja.checkout.web.PedidoRequest;
11	import com.loja.checkout.web.ResumoResponse;
12	import org.springframework.stereotype.Service;
13	
14	import java.math.BigDecimal;
15	import java.util.ArrayList;
16	import java.util.List;
17	
18	/**
19	 * Calcula o resumo da compra. Aqui mora o que é igual em todo pedido: a ordem das
20	 * verificações e a sequência do cálculo descritas no enunciado. O comportamento
21	 * que muda de caso para caso fica nas dimensões (entrega, cupom, clube, pagamento).
22	 */
23	@Service
24	public class CalculadoraResumo {
25	
26	    private final RegistroPorCodigo<ModalidadeEntrega> entregas;
27	    private final RegistroPorCodigo<Cupom> cupons;
28	    private final RegistroPorCodigo<NivelClube> niveis;
29	    private final RegistroPorCodigo<FormaPagamento> pagamentos;
30	
31	    public CalculadoraResumo(RegistroPorCodigo<ModalidadeEntrega> entregas,
32	                             RegistroPorCodigo<Cupom> cupons,
33	                             RegistroPorCodigo<NivelClube> niveis,
34	                             RegistroPorCodigo<FormaPagamento> pagamentos) {
35	        this.entregas = entregas;
36	        this.cupons = cupons;
37	        this.niveis = niveis;
38	        this.pagamentos = pagamentos;
39	    }
40	
41	    public ResumoResponse calcular(PedidoRequest pedido) {
42	        // 1. Itens válidos -> subtotal e peso.
43	        List<ItemPedido> itens = validarItens(pedido.itens());
44	        BigDecimal subtotal = Dinheiro.centavos(somaProdutos(itens));
45	        BigDecimal pesoTotal = somaPeso(itens);
46	
47	        // 2-5. Clube, região e entrega.
48	        NivelClube nivel = niveis.buscar(pedido.nivelClube())
49	                .orElseThrow(() -> new PedidoRecusadoException(CodigoErro.NIVEL_CLUBE_INVALIDO));
50	        Regiao regiao = Regiao.porNome(pedido.regiao())
51	                .orElseThrow(() -> new PedidoRecusadoException(CodigoErro.REGIAO_INVALIDA));
52	        ModalidadeEntrega modalidade = entregas.buscar(pedido.modalidadeEntrega())
53	                .orElseThrow(() -> new PedidoRecusadoException(CodigoErro.MODALIDADE_INVALIDA));
54	        if (!modalidade.atende(pesoTotal)) {
55	            throw new PedidoRecusadoException(CodigoErro.MODALIDADE_INDISPONIVEL);
56	        }
57	
58	        // Frete efetivo: o do clube ouro é zerado.
59	        BigDecimal frete = nivel.isentaFrete()
60	                ? Dinheiro.zero()
61	                : Dinheiro.centavos(modalidade.frete(pesoTotal));
62	
63	        // 6-7. Cupom (opcional).
64	        BigDecimal desconto = calcularDesconto(pedido.cupom(), new ContextoCupom(subtotal, frete, itens));
65	
66	        // Seguro: só a porcentagem muda; a conta é a mesma.
67	        BigDecimal seguro = Dinheiro.centavos(subtotal.multiply(regiao.percentualSeguro()));
68	
69	        // Total do pedido = produtos - desconto + frete + seguro.
70	        BigDecimal totalPedido = Dinheiro.centavos(subtotal.subtract(desconto).add(frete).add(seguro));
71	
72	        // 8-10. Pagamento.
73	        FormaPagamento pagamento = pagamentos.buscar(pedido.formaPagamento())
74	                .orElseThrow(() -> new PedidoRecusadoException(CodigoErro.FORMA_PAGAMENTO_INVALIDA));
75	        int parcelas = pedido.parcelas() == null ? 1 : pedido.parcelas();
76	        if (!pagamento.parcelasPermitidas(parcelas)) {
77	            throw new PedidoRecusadoException(CodigoErro.PARCELAMENTO_INVALIDO);
78	        }
79	        if (!pagamento.atende(totalPedido)) {
80	            throw new PedidoRecusadoException(CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
81	        }
82	
83	        ResultadoPagamento resultado = pagamento.calcular(totalPedido, parcelas);
84	        BigDecimal ajuste = Dinheiro.centavos(resultado.totalFinal().subtract(totalPedido));
85	
86	        BigDecimal credito = Dinheiro.centavos(nivel.credito(subtotal));
87	        boolean brinde = nivel.temBrinde(subtotal);
88	
89	        return new ResumoResponse(
90	                subtotal,
91	                desconto,
92	                frete,
93	                modalidade.prazoDias(),
94	                seguro,
95	                ajuste,
96	                resultado.totalFinal(),
97	                parcelas,
98	                resultado.valorParcela(),
99	                credito,
100	                brinde);
101	    }
102	
103	    private BigDecimal calcularDesconto(String codigoCupom, ContextoCupom ctx) {
104	        if (codigoCupom == null) {
105	            return Dinheiro.zero();
106	        }
107	        Cupom cupom = cupons.buscar(codigoCupom)
108	                .orElseThrow(() -> new PedidoRecusadoException(CodigoErro.CUPOM_INVALIDO));
109	        if (!cupom.aplicavel(ctx)) {
110	            throw new PedidoRecusadoException(CodigoErro.CUPOM_NAO_APLICAVEL);
111	        }
112	        return Dinheiro.centavos(cupom.desconto(ctx));
113	    }
114	
115	    private List<ItemPedido> validarItens(List<ItemRequest> itens) {
116	        if (itens == null || itens.isEmpty()) {
117	            throw new PedidoRecusadoException(CodigoErro.PEDIDO_INVALIDO);
118	        }
119	        List<ItemPedido> validos = new ArrayList<>();
120	        for (ItemRequest item : itens) {
121	            if (naoPositivo(item.precoUnitario()) || item.quantidade() == null || item.quantidade() <= 0
122	                    || naoPositivo(item.pesoKg())) {
123	                throw new PedidoRecusadoException(CodigoErro.PEDIDO_INVALIDO);
124	            }
125	            validos.add(new ItemPedido(item.nome(), item.precoUnitario(), item.quantidade(), item.pesoKg()));
126	        }
127	        return validos;
128	    }
129	
130	    private boolean naoPositivo(BigDecimal valor) {
131	        return valor == null || valor.compareTo(BigDecimal.ZERO) <= 0;
132	    }
133	
134	    private BigDecimal somaProdutos(List<ItemPedido> itens) {
135	        BigDecimal total = BigDecimal.ZERO;
136	        for (ItemPedido item : itens) {
137	            total = total.add(item.totalItem());
138	        }
139	        return total;
140	    }
141	
142	    private BigDecimal somaPeso(List<ItemPedido> itens) {
143	        BigDecimal total = BigDecimal.ZERO;
144	        for (ItemPedido item : itens) {
145	            total = total.add(item.pesoItem());
146	        }
147	        return total;
148	    }
149	}
