1	package com.loja.checkout.dominio.pagamento;
2	
3	import com.loja.checkout.dominio.Dinheiro;
4	import org.springframework.stereotype.Component;
5	
6	import java.math.BigDecimal;
7	import java.math.RoundingMode;
8	
9	/**
10	 * Cartão de crédito: de 1 a 12 parcelas. Até 3x sem juros (o valor final é o
11	 * próprio total e a parcela é o total dividido pelas parcelas). De 4x a 12x com
12	 * juros de 1,99% ao mês pela tabela Price; o valor final é a parcela vezes o
13	 * número de parcelas.
14	 */
15	@Component
16	public class Cartao implements FormaPagamento {
17	
18	    private static final int SEM_JUROS_ATE = 3;
19	    private static final int MAXIMO_PARCELAS = 12;
20	    private static final double TAXA_MENSAL = 0.0199;
21	    private static final int ESCALA_INTERMEDIARIA = 10;
22	
23	    @Override
24	    public String codigo() {
25	        return "CARTAO";
26	    }
27	
28	    @Override
29	    public boolean parcelasPermitidas(int parcelas) {
30	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
31	    }
32	
33	    @Override
34	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
35	        if (parcelas <= SEM_JUROS_ATE) {
36	            BigDecimal parcela = Dinheiro.centavos(
37	                    totalPedido.divide(BigDecimal.valueOf(parcelas), ESCALA_INTERMEDIARIA, RoundingMode.HALF_EVEN));
38	            return new ResultadoPagamento(totalPedido, parcela);
39	        }
40	        double coeficiente = TAXA_MENSAL / (1 - Math.pow(1 + TAXA_MENSAL, -parcelas));
41	        BigDecimal parcela = Dinheiro.centavos(totalPedido.multiply(BigDecimal.valueOf(coeficiente)));
42	        BigDecimal totalFinal = Dinheiro.centavos(parcela.multiply(BigDecimal.valueOf(parcelas)));
43	        return new ResultadoPagamento(totalFinal, parcela);
44	    }
45	}
