4	import java.util.HashMap;
5	import java.util.Map;
6	import java.util.Optional;
7	
8	/**
9	 * Busca de um caso pelo seu código. É igual para entregas, cupons, níveis do
10	 * clube e formas de pagamento, então mora num lugar só. A escolha do caso é um
11	 * acesso a mapa, não uma sequência de condições. Adicionar um caso novo é só
12	 * registrar mais um bean da dimensão correspondente.
13	 */
14	public class RegistroPorCodigo<T extends Codificado> {
15	
16	    private final Map<String, T> porCodigo;
17	
18	    public RegistroPorCodigo(Collection<T> casos) {
19	        Map<String, T> mapa = new HashMap<>();
20	        for (T caso : casos) {
21	            mapa.put(caso.codigo(), caso);
22	        }
23	        this.porCodigo = Map.copyOf(mapa);
24	    }
25	
26	    public Optional<T> buscar(String codigo) {
27	        if (codigo == null) {
28	            return Optional.empty();
29	        }
30	        return Optional.ofNullable(porCodigo.get(codigo));
31	    }
32	}
