                List.of(item("Camiseta", "79.90", 0, "0.30")),
                "EXPRESSA", null, "PIX", 1, "BRONZE", "SUDESTE")))
                .isInstanceOf(PedidoRecusadoException.class)
                .extracting(e -> ((PedidoRecusadoException) e).codigo())
                .isEqualTo(CodigoErro.PEDIDO_INVALIDO);
